using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.FireMoss;

/// <summary>
/// Fire moss, a dark cushion of moss under a haze of red stalks that is the first to cover burnt ground, in the
/// Ashlands. Model: generated by AssetSource/Tools/make_forage_models.py. Nothing else gives it.
/// </summary>
public class FireMoss : ForageableBase
{
    /// <summary>
    /// Prefab name of the fire moss item.
    /// </summary>
    public const string PrefabName = "WhiteHiltFireMoss";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Fire Moss";

    /// <inheritdoc/>
    protected override string Description => "A dark cushion of moss under a haze of red stalks. It is the first to cover burnt ground, and it smoulders slowly in a smokehouse.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "firemoss", 0.12f);
    }
}
